import React from 'react'
import { useTranslation } from 'react-i18next'
import { ExternalLink } from 'lucide-react'
import { Link } from 'gatsby'
import ProfileAvatar from '../auth/ProfileAvatar'
import { getVenueByIdAndLocale } from '../../../data/venues'
import { getInitialFromName } from '../../../utils/profileUtils'
import { getPrefectureGradient } from '../../../data/prefectureColors'

interface AttendeeCardProps {
  userId: string
  username: string
  fullName: string | null
  avatarUrl: string | null
  venueIds: string[]
  comment?: string
  commentDate?: string
}

export const AttendeeCard: React.FC<AttendeeCardProps> = ({
  userId,
  username,
  fullName,
  avatarUrl,
  venueIds,
  comment,
}) => {
  const { i18n } = useTranslation()
  const locale = i18n.language as 'ja' | 'en'

  const displayName = fullName || username || userId

  // 英語の都道府県名を日本語にマッピング（グラデーション取得用）
  const prefectureEnToJa: Record<string, string> = {
    'Tokyo': '東京都',
    'Osaka': '大阪府',
    'Aichi': '愛知県',
    'Fukuoka': '福岡県',
    'Hokkaido': '北海道',
    'Miyagi': '宮城県',
    'Tochigi': '栃木県',
    'Kanagawa': '神奈川県',
    'Niigata': '新潟県',
    'Ishikawa': '石川県',
    'Shizuoka': '静岡県',
    'Kyoto': '京都府',
    'Hyogo': '兵庫県',
    'Hiroshima': '広島県',
    'Ehime': '愛媛県',
    'Nagasaki': '長崎県',
    'Kumamoto': '熊本県',
    'Kagoshima': '鹿児島県',
    'Okinawa': '沖縄県'
  }

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg p-4 border border-gray-200 dark:border-gray-700 shadow-sm hover:shadow-md transition-shadow">
      {/* ユーザー情報 */}
      <div className="flex items-start gap-3 mb-3">
        <ProfileAvatar
          username={username}
          fullName={fullName}
          avatarUrl={avatarUrl}
          size="medium"
        />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h4 className="font-semibold text-gray-900 dark:text-white truncate">
              {displayName}
            </h4>
            <a
              href={`https://x.com/${userId.trim()}`}
              target="_blank"
              rel="noopener noreferrer"
              className="text-gray-400 hover:text-blue-500 dark:text-gray-500 dark:hover:text-blue-400 transition-colors flex-shrink-0"
              aria-label={`@${userId}のXアカウントを開く`}
            >
              <ExternalLink className="h-4 w-4" />
            </a>
          </div>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            @{userId}
          </p>
        </div>
      </div>

      {/* コメント */}
      {comment && (
        <div className="mb-3 p-2 bg-gray-50 dark:bg-gray-700/50 rounded text-sm text-gray-700 dark:text-gray-300">
          {comment}
        </div>
      )}

      {/* 参加会場都道府県アイコン */}
      <div className="flex flex-wrap gap-1.5">
        {venueIds
          .map(venueId => {
            const venue = getVenueByIdAndLocale(venueId, locale)
            return venue ? { venueId, venue } : null
          })
          .filter((item): item is { venueId: string; venue: any } => item !== null)
          .sort((a, b) => new Date(a.venue.date).getTime() - new Date(b.venue.date).getTime())
          .map(({ venueId, venue }) => {
            const prefectureInitial = getInitialFromName(venue.location.prefecture)
            // 英語の都道府県名を日本語に変換してからグラデーション取得
            const prefectureForGradient = locale === 'en' 
              ? (prefectureEnToJa[venue.location.prefecture] || venue.location.prefecture)
              : venue.location.prefecture
            const gradient = venue.gradient
              ? `linear-gradient(135deg, ${venue.gradient.from}, ${venue.gradient.to})`
              : getPrefectureGradient(prefectureForGradient)

            return (
              <Link
                key={venueId}
                to={`/bijigaku-navi/venue/${venueId}/`}
                className="w-8 h-8 rounded-full flex items-center justify-center text-white font-bold text-xs shadow-sm hover:scale-110 transition-transform cursor-pointer"
                style={{ background: gradient }}
                title={`${venue.location.prefecture} - ${venue.name}`}
              >
                {prefectureInitial}
              </Link>
            )
          })}
      </div>
    </div>
  )
}
